python3 << 'EOF'
import re

# Read the page file
with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

# Extract the monthly data table
rows = re.findall(r'<tr><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td><td>(.*?)</td></tr>', content, re.DOTALL)

# Filter to get only data rows (month rows)
data_rows = []
for row in rows:
    month = row[0].strip()
    if month in ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']:
        data_rows.append([cell.strip() for cell in row])

# Based on yield levels, let me map out the years:
# Group 1 (cols 1,2): Treasury ~3.9-4.3%, Corporate ~4.5-5.4% → 1960
# Group 2 (cols 4,5): Treasury ~3.9-4.2%, Corporate ~4.2-4.6% → 1961
# Group 3 (cols 7,8): Treasury ~4.1-4.9%, Corporate ~4.5-6.1% → 1962-1963
# Group 4 (cols 10,11): Treasury ~5.0-6.9%, Corporate ~6.5-9.2% → 1965-1968 (later data)

# Let me verify this by checking each group's range of yields
def clean_val(v):
    v = re.sub(r'[\d]/', '', v).strip()
    if v:
        try:
            return float(v)
        except:
            return None
    return None

# Check all 4 groups
for group_idx, (t_col, c_col) in enumerate([(1, 2), (4, 5), (7, 8), (10, 11)]):
    treasury_vals = []
    corp_vals = []
    for row in data_rows[:12]:  # First 12 months
        t = clean_val(row[t_col])
        c = clean_val(row[c_col])
        if t: treasury_vals.append(t)
        if c: corp_vals.append(c)

    if treasury_vals and corp_vals:
        print(f"Group {group_idx+1} (cols {t_col},{c_col}): Treasury range {min(treasury_vals):.2f}-{max(treasury_vals):.2f}%, Corporate range {min(corp_vals):.2f}-{max(corp_vals):.2f}%")

# Check the next 12 months for Group 3 and 4
print("\nNext 12 months (rows 12-23):")
for group_idx, (t_col, c_col) in enumerate([(1, 2), (4, 5), (7, 8), (10, 11)]):
    treasury_vals = []
    corp_vals = []
    for row in data_rows[12:24]:  # Next 12 months
        t = clean_val(row[t_col])
        c = clean_val(row[c_col])
        if t: treasury_vals.append(t)
        if c: corp_vals.append(c)

    if treasury_vals and corp_vals:
        print(f"Group {group_idx+1} (cols {t_col},{c_col}): Treasury range {min(treasury_vals):.2f}-{max(treasury_vals):.2f}%, Corporate range {min(corp_vals):.2f}-{max(corp_vals):.2f}%")

print("\nLast 12 months (rows 24-35):")
for group_idx, (t_col, c_col) in enumerate([(1, 2), (4, 5), (7, 8), (10, 11)]):
    treasury_vals = []
    corp_vals = []
    for row in data_rows[24:36]:  # Last 12 months
        t = clean_val(row[t_col])
        c = clean_val(row[c_col])
        if t: treasury_vals.append(t)
        if c: corp_vals.append(c)

    if treasury_vals and corp_vals:
        print(f"Group {group_idx+1} (cols {t_col},{c_col}): Treasury range {min(treasury_vals):.2f}-{max(treasury_vals):.2f}%, Corporate range {min(corp_vals):.2f}-{max(corp_vals):.2f}%")
EOF
